import {drawPriceBee} from './assets/chart-bee.mjs';
// Isolated design prototype. No API, Telegram, wallet, analytics or signing integration.
const $=s=>document.querySelector(s), screen=$('#screen'), sheet=$('#sheet');
const symbols={
 chart:'<path d="M4 4v16h16M7 15l4-5 4 2 5-7"/>',
 trophy:'<path d="M8 3h8v5a4 4 0 0 1-8 0V3Zm0 2H4v2a4 4 0 0 0 4 4m8-6h4v2a4 4 0 0 1-4 4M12 12v6m-4 3h8m-7-3h6"/>',
 user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>', more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
 gear:'<path d="m9 3-.5 3-2 1-2.5-1L2 10l2.5 2v2L2 16l2 4 2.5-1 2 1 .5 3h5l.5-3 2-1 2.5 1 2-4-2.5-2v-2L22 10l-2-4-2.5 1-2-1L15 3Z" transform="translate(0 -1) scale(1 .96)"/><circle cx="12" cy="12" r="3"/>',
 back:'<path d="m14 5-7 7 7 7"/>', chevron:'<path d="m9 5 7 7-7 7"/>',
 up:'<path d="M12 20V4m-7 7 7-7 7 7"/>',down:'<path d="M12 4v16m-7-7 7 7 7-7"/>',
 northeast:'<path d="M5 19 19 5M5 5h14v14"/>',southeast:'<path d="M5 5 19 19M5 19h14V5"/>',
 wallet:'<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8V5l14-3v3m4 6h-6v5h6"/><path d="M17 13.5h.1"/>',
 people:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m0-17a3 3 0 0 1 0 6m3 3a7 7 0 0 1 3 5v3"/>',
 chat:'<path d="M21 11a9 9 0 0 1-9 9H3v-9a9 9 0 1 1 18 0Z"/><path d="M7 9h10M7 13h7"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
 check:'<path d="m5 12 4 4L19 6"/>', copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v12h5"/>',
 globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
 shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',
 send:'<path d="m22 2-7 20-4-9-9-4Zm0 0L11 13"/>', image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
 coins:'<ellipse cx="9" cy="6" rx="6" ry="3"/><path d="M3 6v6c0 2 3 3 6 3m-6-6c0 2 3 3 6 3m0-3v6c0 2 3 3 6 3s6-1 6-3V9m-12 3c0 2 3 3 6 3s6-1 6-3"/><ellipse cx="15" cy="9" rx="6" ry="3"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>', download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>', pause:'<path d="M8 5v14M16 5v14"/>', refresh:'<path d="M20 7a9 9 0 1 0 1 9M20 3v5h-5"/>', volume:'<path d="m11 4-6 5H2v6h3l6 5Zm4 4a5 5 0 0 1 0 8m3-11a9 9 0 0 1 0 14"/>'
};
const icon=n=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(symbols[n]||symbols.chart)+'</svg>';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const usd=v=>'$'+Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const signed=v=>(v>0?'+':v<0?'−':'')+usd(Math.abs(v));
const number=v=>Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const color=v=>v<0?'negative':v>0?'positive':'';
const duration=s=>s>=60?Math.floor(s/60)+'m '+Math.floor(s%60)+'s':Math.max(0,Math.floor(s))+'s';
const help=(topic,label='More information')=>'<button class="help" data-help="'+topic+'" aria-label="'+label+'"><span>?</span></button>';
const row=(label,value)=>'<div class="line-row"><span>'+label+'</span><b>'+value+'</b></div>';
const entry=(label,go,i='chevron',subtitle='')=>'<button class="entry-row" data-go="'+go+'">'+icon(i)+'<span>'+label+(subtitle?'<small>'+subtitle+'</small>':'')+'</span><span class="chevron">'+icon('chevron')+'</span></button>';
const pages=[['trading','Trading'],['leaderboard','Leaderboard'],['profile','Profile'],['earnings','Earnings'],['history','Public trading history'],['result','Trade result & card'],['deposit','Deposit'],['withdrawal','Withdrawal progress'],['invite','Invite friends'],['invitation','Accept invitation'],['settings','Settings'],['treasury','Public treasury']];
const BASE={paper:1088.10,money:248.50};
const state={route:'trading',mode:'paper',authenticated:true,wallet:true,walletProvider:'telegram',owner:false,preview:'normal',bet:10,leverage:{paper:1000,money:100},balance:{...BASE},earnings:{paper:76,money:128.4},referrals:{paper:12.10,money:12.30},positions:{paper:null,money:null},results:{paper:null,money:null},newTrades:{paper:[],money:[]},selectedTrader:'you',withdrawal:null,deposit:null,price:78124.61,phase:0,paused:false,panned:false,asset:'USDT',depositAmount:'',withdrawAmount:'',range:'All',haptics:true,consent:false,accepted:false};
const walletName=(provider=state.walletProvider)=>provider==='walt'?'Walt DeFi':'Telegram Money';
const walletReview=(provider=state.walletProvider)=> 'Review in '+walletName(provider);
const beeCanvas=document.createElement('canvas');beeCanvas.width=144;beeCanvas.height=144;
function beeSprite(){const ctx=beeCanvas.getContext('2d');ctx.clearRect(0,0,144,144);ctx.save();ctx.scale(2,2);drawPriceBee(ctx,36,36,{now:state.phase*250,live:state.preview!=='stale',reducedMotion:reduced.matches});ctx.restore();return beeCanvas.toDataURL();}
const animals=['🦣','🦤','🐅','🦕','🦤','🦖','🐘','🦤','🦣'];
let modal=null,modalStack=[],pendingDirection=null,toastTimer,chartTimer,previousFocus=null;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const positions=()=>state.positions[state.mode];
const currentResult=()=>state.results[state.mode]||sampleTrade(7.2,1,1000,92);
function sampleTrade(net,side=1,lev=1000,held=92){const margin=10,entry=78124.61,entryFee=.1,gross=net>0?(net+entryFee)/.9:net+entryFee,profitFee=Math.max(0,gross*.1),exit=entry*(1+side*gross/(margin*lev));return {side,leverage:lev,margin,entry,exit,held,gross,entryFee,profitFee,net,mode:state.mode,closed:'Today, 12:38',opened:'12:36:28'};}
function historyTrades(){return [...state.newTrades[state.mode],sampleTrade(7.2,1,1000,92),sampleTrade(-3.1,-1,500,48),sampleTrade(4.6,1,100,75),sampleTrade(-1.2,1,1000,31),sampleTrade(6.8,-1,500,125)];}
function estimate(p){let gross=Math.max(-p.margin,Math.min(p.margin,p.side*(state.price/p.entry-1)*p.margin*p.leverage));let profitFee=Math.max(0,gross*.1);return {gross,profitFee,net:gross-p.margin*.01-profitFee,returned:p.margin+gross-profitFee};}
function tradeItem(t,index=0){return '<button class="trade-item" data-trade="'+index+'"><span class="side-marker '+(t.side===1?'positive':'negative')+'">'+icon(t.side===1?'up':'down')+'</span><span><strong>BTC '+(t.side===1?'long':'short')+'</strong><small>'+t.leverage.toLocaleString()+'× leverage</small></span><span class="result"><strong class="'+color(t.net)+'">'+signed(t.net)+'</strong><small>'+duration(t.held)+'</small></span></button>';}
function title(label,back){return '<div class="page-heading">'+(back?'<button class="back" data-go="'+back+'">'+icon('back')+'<h1>'+label+'</h1></button>':'<h1>'+label+'</h1>')+'</div>';}
function spark(kind='up'){return '<svg class="spark" viewBox="0 0 160 68" role="img" aria-label="Illustrative cumulative earnings"><path d="M2 62H158" stroke="var(--line)"/><path d="M2 57 15 51 29 55 42 43 56 46 70 30 84 34 99 22 114 26 129 12 144 16 158 2" fill="none" stroke="var(--green)" stroke-width="1.7" stroke-linecap="round"/></svg>';}
function chartMarkup(active=false){return '<div class="chart-wrap '+(active?'active-chart ':'')+(state.preview==='stale'?'stale':'')+'" id="market-chart"><svg id="market-svg" role="img" aria-label="Illustrative BTC chart. Sample prices, not a live market feed." viewBox="0 0 350 260" preserveAspectRatio="none"></svg>'+(state.panned?'<span class="chart-hint">Earlier prices</span>':'')+'<button class="live-control" data-action="live" aria-label="Return chart to the latest sample">'+icon('northeast')+' LIVE</button>'+(state.preview==='stale'?'<span class="chart-notice">'+icon('pause')+' Waiting for fresh prices</span>':'')+'</div>';}
function renderChart(){
 const svg=$('#market-svg');if(!svg)return;
 const p=positions(),mid=state.price,h=Math.max(140,svg.getBoundingClientRect().height),bottom=h-32;
 const base=mid-12;let vals=Array.from({length:66},(_,i)=>base+Math.sin(i*.3+state.phase*.08)*7+Math.cos(i*.89)*2+i*.18);
 const shift=mid-vals.at(-1);vals=vals.map(v=>v+shift);if(state.panned)vals=vals.map((v,i)=>v-8+Math.sin(i*.2)*6);
 const lo=Math.min(...vals,p?p.entry:mid)-8,hi=Math.max(...vals,p?p.entry:mid)+8,yy=v=>22+(hi-v)/(hi-lo)*(bottom-22);
 const tail=state.panned?vals.at(-1):mid,path=vals.map((v,i)=>(i?'L':'M')+(12+i*(248/65)).toFixed(1)+','+yy(v).toFixed(1)).join(' '),y=yy(tail),ticks=[hi-2,(hi+lo)/2,lo+2];
 svg.setAttribute('viewBox','0 0 350 '+h);
 const bee=p&&!state.panned?'<image class="price-bee" href="'+beeSprite()+'" x="234" y="'+(y-26).toFixed(1)+'" width="52" height="52" aria-hidden="true"/>':'';
 svg.innerHTML='<defs><linearGradient id="chart-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="var(--yellow)" stop-opacity=".13"/><stop offset="100%" stop-color="var(--yellow)" stop-opacity="0"/></linearGradient></defs>'+ticks.map(v=>'<path d="M12 '+yy(v).toFixed(1)+'H285" stroke="var(--line)" stroke-width=".5"/><text x="291" y="'+(yy(v)+3).toFixed(1)+'" class="chart-axis">'+Math.round(v).toLocaleString()+'</text>').join('')+'<path d="M100 16V'+bottom+'M205 16V'+bottom+'" stroke="var(--line)" stroke-width=".5"/>'+(p?'<path d="M12 '+yy(p.entry).toFixed(1)+'H285" stroke="var(--muted)" stroke-width=".8" stroke-dasharray="3 4"/><text x="15" y="'+(yy(p.entry)-7).toFixed(1)+'" class="chart-axis">ENTRY '+number(p.entry)+'</text>':'')+'<path d="'+path+'L260,'+bottom+'H12Z" fill="url(#chart-fill)"/><path d="'+path+'" fill="none" stroke="var(--yellow)" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/><path d="M260 '+y.toFixed(1)+'H300" stroke="var(--yellow)" stroke-width="1" stroke-dasharray="3 4"/><circle class="pulse-ring" cx="260" cy="'+y.toFixed(1)+'" r="7" fill="var(--yellow)" opacity=".3"/><circle cx="260" cy="'+y.toFixed(1)+'" r="3.6" fill="#fff1a1"/>'+bee+'<rect x="295" y="'+(y-10).toFixed(1)+'" width="55" height="21" rx="5" fill="var(--yellow)"/><text x="299" y="'+(y+4).toFixed(1)+'" class="chart-label">'+Math.round(tail).toLocaleString()+'</text><text x="40" y="'+(h-10)+'" class="chart-axis">12:36:00</text><text x="205" y="'+(h-10)+'" class="chart-axis">12:37:00</text>';
}
function trading(){const p=positions();const balanceLabel=state.mode==='paper'?'Paper balance':'Trading balance';let top='<div class="trading-top"><button class="brand-mark" data-go="trading" aria-label="Trading home"><img src="assets/logo.png" alt=""></button><button class="balance-chip" data-action="balance"><div><small>'+balanceLabel+'</small><strong>'+usd(state.balance[state.mode])+'</strong></div><span>+</span></button></div>';
 if(p){const x=estimate(p),left=state.mode==='money'?Math.max(0,30-Math.floor((Date.now()-p.openedAt)/1000)):0,delayed=state.preview==='stale';return top+'<div class="position-top"><span class="eyebrow">'+(p.side===1?'LONG':'SHORT')+' · '+p.leverage.toLocaleString()+'× · OPEN</span><div class="pnl '+color(x.net)+'" id="active-pnl">'+(delayed?'—':(x.net>=0?'+':'')+(x.net/p.margin*100).toFixed(2)+'%')+'</div><div class="subtitle"><span id="active-value">'+(delayed?'Price delayed':signed(x.net))+'</span> · estimated net P&L '+help('execution','How trade P&L is estimated')+'</div></div>'+chartMarkup(true)+'<button class="exit-button" data-action="exit" '+(left||delayed?'disabled':'')+'><strong id="exit-title">'+(left?'Hold '+left+'s':delayed?'PRICE DELAYED':'CASH OUT')+'</strong><span id="exit-return">'+(delayed?'Waiting for a fresh price':usd(x.returned)+' estimated return')+'</span></button><div class="position-foot"><span>Time inside <b id="time-inside">'+duration((Date.now()-p.openedAt)/1000)+'</b></span><button data-help="risk">Risk '+icon('chevron')+'</button></div>';}
 return top+chartMarkup()+'<div class="dials"><button class="dial-button" data-action="bet" '+(state.mode==='money'?'disabled':'')+' aria-label="Bet size '+usd(state.mode==='money'?10:state.bet)+(state.mode==='money'?'. Fixed Money stake.':'. Tap to cycle 10, 50 and 100 dollars.')+'"><span class="dial" aria-hidden="true"></span><span class="dial-copy"><small>Your bet'+(state.mode==='money'?' · fixed':'')+'</small><strong>'+usd(state.mode==='money'?10:state.bet).replace('.00','')+'</strong></span></button><button class="dial-button" data-action="leverage" aria-label="Leverage '+state.leverage[state.mode]+' times. Tap to cycle 100, 500 and 1000 times."><span class="dial" aria-hidden="true"></span><span class="dial-copy"><small>Leverage</small><strong>'+state.leverage[state.mode].toLocaleString()+'×</strong></span></button>'+help('setup','Trading setup and fees')+'</div><div class="hands"><button class="hand-button" data-side="1" '+(state.preview==='stale'?'disabled':'')+' aria-label="UP — open long"><img src="assets/hand.svg" alt=""><strong class="positive">UP '+icon('northeast')+'</strong><small>BUY · OPEN LONG</small></button><button class="hand-button down" data-side="-1" '+(state.preview==='stale'?'disabled':'')+' aria-label="DOWN — open short"><img src="assets/hand.svg" alt=""><strong class="negative">DOWN '+icon('southeast')+'</strong><small>SELL · OPEN SHORT</small></button></div>'+(state.preview==='stale'?'<div class="trade-note">'+icon('pause')+' Trading waits for a fresh price</div>':!state.authenticated?'<button class="text-link" data-action="login">Log in with Telegram to play</button>':'');}
function profile(){if(!state.authenticated)return signedOut();const m=state.mode,total=state.earnings[m]+state.referrals[m];return '<div class="identity"><span class="avatar" role="img" aria-label="Dodo avatar">🦤</span><strong>@boogaav</strong><button class="icon quiet" data-go="settings" aria-label="Profile settings">'+icon('gear')+'</button></div><div class="eyebrow brand">'+(m==='paper'?'PAPER':'AVAILABLE')+' · USD</div><div class="profile-amount amount">'+usd(state.balance[m])+'</div><span class="currency-note">'+(m==='paper'?'Virtual balance':'USDT on TON')+'</span><div class="actions">'+(m==='paper'?'<button class="primary" data-go="trading">Trade Paper</button><button class="secondary" data-action="money">Go to Money</button>':'<button class="primary" data-action="deposit">Deposit</button><button class="secondary" data-action="withdraw">Withdraw</button>')+'</div>'+(m==='money'&&state.withdrawal?withdrawShort():'')+'<section class="panel earnings"><div class="earnings-top"><span>Your earnings '+help('earnings','What counts as earnings')+'</span><span><small>All time</small><button class="icon quiet" data-go="earnings" aria-label="View earnings details">'+icon('chevron')+'</button></span></div><div class="earnings-total '+color(total)+'">'+signed(total)+'</div><div class="earnings-bottom"><div class="earnings-breakdown">Trading <strong>'+signed(state.earnings[m])+'</strong><br>Invitations <strong>'+signed(state.referrals[m])+'</strong></div>'+spark()+'</div></section><div class="section-heading">Recent trades <small>Closed</small></div>'+historyTrades().slice(0,2).map((t,i)=>tradeItem(t,i)).join('')+'<div class="profile-links">'+entry('Invite friends','invite','people')+entry('Contact us','support','chat')+'</div><button class="logout" data-action="logout">Log out</button>';}
function signedOut(){return '<div class="welcome"><span class="avatar" aria-hidden="true">🦤</span><h1>Your next move<br>starts here.</h1><p>Practice with live BTC prices and virtual money.</p><button class="primary" data-action="login">Log in with Telegram</button><button class="text-link" data-help="paper">What is Paper Hands?</button></div>'+entry('Contact us','support','chat');}
function withdrawLabel(){const w=state.withdrawal;return !w?'Manual review':w.status==='held'?'On hold':w.status==='ready'?'Ready to claim':w.status==='submitted'?'Confirming receipt':w.status==='paid'?'Received':'Manual review';}
function withdrawShort(){const w=state.withdrawal;return '<button class="withdrawal-short" data-go="withdrawal">'+icon(w.status==='paid'?'check':'clock')+'<span><strong>'+number(w.amount)+' USDT · '+withdrawLabel()+'</strong><small>'+ (w.status==='paid'?'Receipt confirmed':'Waiting '+duration((Date.now()-w.created)/1000))+'</small></span><span class="arrow">'+icon('chevron')+'</span></button>';}
function boardRows(){const money=state.mode==='money',values=money?[511.2,248.9,201.4,state.earnings.money,54.5,32.8,8.6,-2.1,-29]:[326.4,214.5,161.2,98.6,state.earnings.paper,54.2,21,-3.1,-17];return values.map((p,i)=>({id:i===4&&!money||i===3&&money?'you':'demo'+i,name:i===4&&!money||i===3&&money?'boogaav':['demo_mammoth','demo_dodo','demo_tiger','demo_dino','demo_finch','demo_raptor','demo_elephant','demo_kiwi','demo_sloth'][i],animal:animals[i],net:p,trades:41+i*5})).sort((a,b)=>b.net-a.net);}
function boardRow(u,i){return '<button class="leader-row '+(u.id==='you'?'you':'')+'" data-user="'+u.id+'"><span class="rank">'+(i+1)+'</span><span class="avatar small" aria-hidden="true">'+(u.id==='you'?'🦤':u.animal)+'</span><span class="trader"><strong>@'+u.name+(u.id==='you'?' · You':'')+'</strong><small>'+u.trades+' closed trades</small></span><span class="leader-pnl '+color(u.net)+'">'+signed(u.net)+icon('chevron')+'</span></button>';}
function leaderboard(){let head='<div class="page-heading"><h1>Leaderboard</h1>'+help('leaderboard','How rankings are calculated')+'</div>';
 if(state.preview==='empty')return head+'<div class="state-message">'+icon('trophy')+'<h2>Your first finish.</h2><p>Close a trade to join the '+(state.mode==='paper'?'Paper':'Money')+' ranking.</p><button class="primary" data-go="trading">Back to trading</button></div>';
 if(state.preview==='board-error')return head+'<div class="state-message">'+icon('refresh')+'<h2>Rankings are taking a break.</h2><p>Your balance and trades are unchanged.</p><button class="secondary" data-action="retry-board">Try again</button></div>';
 const users=boardRows();return head+'<div class="board-top"><small>All time</small><strong>Net P&L</strong></div><div class="board-lead"><span class="trophy">'+icon('trophy')+'</span><span class="eyebrow">Leading the way</span>'+boardRow(users[0],0)+'</div>'+users.slice(1).map((u,i)=>boardRow(u,i+1)).join('');}
function history(){const u=boardRows().find(u=>u.id===state.selectedTrader)||boardRows()[0];return '<div class="page-heading"><button class="back" data-go="leaderboard">'+icon('back')+'<h1>Trading history</h1></button>'+help('public','What is public')+'</div><div class="history-hero"><span class="avatar" aria-hidden="true">'+(u.id==='you'?'🦤':u.animal)+'</span><div><strong>@'+u.name+'</strong><small>'+ (state.mode==='paper'?'Paper Hands':'Money')+'</small></div></div><div class="eyebrow">Net closed-trade P&L</div><div class="history-pnl '+color(u.net)+'">'+signed(u.net)+'</div><div class="stats-row"><div><strong>'+u.trades+'</strong><small>Closed trades</small></div><div><strong>61%</strong><small>Win rate</small></div><div><strong>1m 18s</strong><small>Avg. time inside</small></div></div><div class="bars" role="img" aria-label="Illustrative recent positive and negative trade results">'+[25,-12,36,18,-24,42,-8,27,13,-20,39,32].map(h=>'<i class="'+(h<0?'loss':'')+'" style="--h:'+Math.abs(h)+'px"></i>').join('')+'</div><div class="section-heading">Closed trades</div>'+historyTrades().map((t,i)=>tradeItem(t,i)).join('');}
function earnings(){let total=state.earnings[state.mode]+state.referrals[state.mode],factor=state.range==='7D'?.28:state.range==='30D'?.64:1;total*=factor;return '<div class="page-heading"><button class="back" data-go="profile">'+icon('back')+'<h1>Earnings</h1></button>'+help('earnings','What counts as earnings')+'</div><div class="asset-tabs" style="grid-template-columns:repeat(3,1fr)">'+['7D','30D','All'].map(t=>'<button data-range="'+t+'" aria-pressed="'+(state.range===t)+'">'+t+'</button>').join('')+'</div><div class="eyebrow">'+(state.mode==='paper'?'Paper':'Money')+' · '+(state.range==='All'?'All-time':state.range)+' earnings</div><div class="history-pnl '+color(total)+'">'+signed(total)+'</div><div class="panel">'+row('Net trading P&L','<span class="'+color(state.earnings[state.mode])+'">'+signed(state.earnings[state.mode]*factor)+'</span>')+row('Invitation rewards',signed(state.referrals[state.mode]*factor))+'</div><section class="panel"><div class="section-heading" style="margin:0 0 12px">Cumulative earnings</div>'+spark()+'<div class="board-top" style="margin:12px 0 0"><small>First trade</small><small>Today</small></div></section><div class="stats-row"><div><strong>41</strong><small>Closed trades</small></div><div><strong>61%</strong><small>Win rate</small></div><div><strong>1m 18s</strong><small>Avg. time inside</small></div></div>';}
function trace(t){const points=[[10,90],[34,91],[56,76],[79,81],[103,58],[126,66],[151,46],[176,51],[200,30],[226,40],[249,21],[276,26],[310,12]],down=t.exit<t.entry,ys=points.map(([x,y])=>[x,down?104-y:y]),path=ys.map(([x,y],i)=>(i?'L':'M')+x+' '+y).join(' ');return '<svg class="trace" viewBox="0 0 320 130" role="img" aria-label="Illustrative trade price trace with entry and exit"><path d="M10 22H310M10 64H310M10 106H310" stroke="var(--line)"/><path d="'+path+'" stroke="var(--yellow)" stroke-width="2" fill="none"/><circle cx="10" cy="'+ys[0][1]+'" r="4" fill="var(--yellow)"/><circle cx="310" cy="'+ys.at(-1)[1]+'" r="4" fill="var(--yellow)"/><text x="10" y="127">ENTRY</text><text x="281" y="127">EXIT</text></svg>';}
function resultPage(){const t=currentResult();return '<div class="result-hero"><span class="pill '+(state.mode==='money'?'money':'')+'">'+(state.mode==='money'?'Money':'Paper Hands')+'</span><h1>Trade closed.</h1><div class="big-return '+color(t.net)+'">'+(t.net>=0?'+':'')+(t.net/t.margin*100).toFixed(2)+'%</div><div class="return-caption">'+signed(t.net)+' net P&L '+help('fees','Trade fee breakdown')+'</div></div><div class="panel"><div class="trade-detail-title"><h2>BTC '+(t.side===1?'long':'short')+'</h2><span class="eyebrow">'+t.leverage.toLocaleString()+'×</span></div>'+trace(t)+row('Price in',number(t.entry))+row('Price out',number(t.exit))+row('Time inside',duration(t.held))+'</div><button class="primary" data-action="card">'+icon('image')+' Create trade card</button><button class="text-link" data-go="trading">Back to trading '+icon('arrow')+'</button>';}
function cardMarkup(t){return '<div class="trade-card"><div class="card-brand"><div class="card-wordmark">YELLOW<br>HANDS<small>TRADE RESULT</small></div><img src="assets/logo.png" alt="Yellow Hands"></div><div class="card-user">@'+esc(t.username||'boogaav')+' · '+(state.mode==='money'?'MONEY':'PAPER HANDS')+'</div><h2 class="'+color(t.net)+'">'+(t.net>=0?'+':'')+(t.net/t.margin*100).toFixed(2)+'%</h2><div class="card-result '+color(t.net)+'">'+signed(t.net)+'</div><span class="eyebrow">BTC '+(t.side===1?'LONG':'SHORT')+' · '+t.leverage.toLocaleString()+'×</span>'+trace(t)+'<div class="card-data"><div><small>Price in</small>'+number(t.entry)+'</div><div><small>Price out</small>'+number(t.exit)+'</div><div><small>Time inside</small>'+duration(t.held)+'</div><div><small>Margin</small>'+usd(t.margin)+'</div></div><div class="card-url">ton.yellowhands.wtf · net P&L after fees</div></div>';}
function invite(){let rate=state.mode==='paper'?10:5,reward=state.referrals[state.mode];return title('Invite friends','profile')+'<div class="invite-hero"><span class="avatar" aria-hidden="true">🦣</span><h1>Better with friends.</h1><div class="reward-rate">'+rate+'%</div><p>Of your friends’ net winning-trade profits. Ongoing.</p></div><div class="section-heading">Your rewards '+help('referrals','Invitation reward rules')+'</div><div class="panel"><div class="earnings-total '+color(reward)+'" style="margin-top:0">'+signed(reward)+'</div><div class="stats-row" style="margin-bottom:0"><div><strong>12</strong><small>Confirmed</small></div><div><strong>7</strong><small>Active traders</small></div></div>'+(state.mode==='money'?'<button class="text-link" data-action="collect">Move available rewards to balance '+icon('arrow')+'</button>':'')+'</div><div class="panel"><span class="eyebrow">Your invitation</span><div class="invite-code"><strong>DEMOYH01</strong><button class="icon" data-action="copy" aria-label="Copy invitation link">'+icon('copy')+'</button></div><p class="invite-link">t.me/yellowhandsbot?startapp=ref_DEMOYH01</p></div><button class="primary" data-action="share-invite">'+icon('send')+' Share in Telegram</button><div class="actions"><button class="secondary" data-action="copy">Copy link</button><button class="secondary" data-action="instagram">Instagram kit</button></div><button class="text-link" data-go="invitation">Have an invitation?</button>';}
function invitation(){return title('Your invitation','invite')+'<div class="invite-confirm"><span class="avatar" aria-hidden="true">🦣</span><h2>'+ (state.accepted?'You’re connected.':'@demo_mammoth invited you.')+'</h2><p>'+ (state.accepted?'Your invitation is confirmed. Your winnings stay yours.':'Your winnings stay yours. Your friend earns a reward funded by Yellow Hands.')+'</p><button class="primary" data-action="accept-invite">'+(state.accepted?'Start Paper Hands':'Accept invitation')+'</button>'+help('invitation','Invitation confirmation rules')+'</div>';}
function withdrawal(){const w=state.withdrawal;if(!w)return title('Withdrawals','profile')+'<div class="state-message">'+icon('wallet')+'<h2>Nothing waiting.</h2><p>Your USDT withdrawal requests will appear here.</p><button class="primary" data-action="withdraw">Withdraw USDT</button></div>';let label=withdrawLabel(),elapsed=duration((Date.now()-w.created)/1000),step=w.status==='paid'?4:w.status==='submitted'?3:w.status==='ready'?2:1;
 return title('Withdrawal','profile')+'<div class="status-top"><span class="pill '+(w.status==='held'?'held':w.status==='paid'?'money':'wait')+'">'+label+'</span>'+help('manual','Why withdrawals use manual review during beta')+'</div><div class="flow-amount">'+number(w.amount)+' USDT</div><p class="flow-subtitle" id="withdraw-time">'+(w.status==='paid'?'Receipt confirmed':'Waiting '+elapsed)+'</p><div class="panel" style="margin-top:22px">'+row('To wallet',walletName(w.walletProvider)+' · UQ…example')+'</div><ol class="timeline"><li class="done">Requested<small>'+usd(w.amount)+' reserved from your USD balance</small></li><li class="'+(step>=2?'done':'now')+'">'+(w.status==='held'?'On hold':'Manual review')+'<small>'+(step>=2?'Approved':w.status==='held'?'Contact support for the next step':'Waiting for operator approval')+'</small></li><li class="'+(step>2?'done':step===2?'now':'next')+'">Claim in wallet<small>'+(step>=3?'Claim submitted':'Wallet signature + network fee')+'</small></li><li class="'+(step===4?'done':step===3?'now':'next')+'">Received<small>'+(step===4?'Verified by the receipt':'After confirmed on-chain receipt')+'</small></li></ol>'+(w.status==='ready'?'<button class="primary" data-action="claim">Claim '+number(w.amount)+' USDT</button>':w.status==='submitted'?'<button class="secondary" disabled>Confirming on TON…</button>':w.status==='paid'?'<button class="secondary" data-help="receipt">View receipt</button>':'<button class="secondary" data-go="support">Contact us</button>');}
function settings(){return title('Settings','profile')+'<div class="settings-label">ACCOUNT</div>'+entry('Wallet','wallet','wallet',state.wallet?walletName()+' · UQ…example':'Not connected')+entry('Language','language','globe','From Telegram · English')+entry('Haptics','haptics','volume',state.haptics?'On during trades':'Off')+entry('Usage analytics','consent','shield',state.consent?'Allowed':'Not allowed')+entry('Public treasury','treasury','coins')+entry('Contact us','support','chat')+(state.owner?'<div class="settings-label">OWNER ONLY</div>'+entry('Liquidity management','liquidity','coins')+entry('Private analytics','analytics','chart'):'')+'<button class="logout" data-action="logout">Log out of Telegram</button><div class="legal-links"><button data-help="terms">Trading terms</button><button data-help="privacy">Privacy</button></div>';}
function treasury(owner=false){return title(owner?'Liquidity management':'Public treasury',owner?'settings':'settings')+'<div class="eyebrow">USDT on TON · sample reserves</div><div class="treasury-number">10,000.00</div><p class="currency-note">USDT</p><div class="allocation" role="img" aria-label="Illustrative target allocation: 80 percent reserve, 20 percent withdrawal liquidity"><span class="reserve"></span><span class="hot"></span></div><div class="allocation-labels"><div>Reserve · 80%<small>8,000.00 USDT</small></div><div>Hot liquidity · 20%<small>2,000.00 USDT</small></div></div><div class="section-heading">Treasury backing '+help('treasury','Treasury and custody details')+'</div><div class="panel">'+row('USDT reserves','10,000.00 USDT')+row('Native gas balance','12.40 GRAM')+row('Updated','Just now')+'</div>'+ (owner?'<div class="panel">'+row('Target reserve / hot split','80% / 20%')+row('Pending withdrawals','20.00 USDT')+row('Gas auto-refill','Off')+'</div><button class="primary" data-action="fund-treasury">Fund treasury</button><button class="secondary" style="margin-top:12px" data-action="lp-add">Allocate USD credit to LP</button><button class="text-link" data-help="lp">LP mechanics '+icon('chevron')+'</button>':'<button class="secondary" data-help="explorer">View treasury on TON '+icon('northeast')+'</button>');}
const helpCopy={
 earnings:['What counts as earnings?','Net profit from closed trades after fees, plus earned invitation rewards. Deposits, returned stakes and open trades are excluded. Paper earnings also exclude starter credit and cannot be withdrawn.'],
 manual:['Manual review during beta','During beta, our team reviews withdrawals manually. Your funds stay reserved while you wait. Once approved and ready, claim USDT in your wallet. A network fee applies. Contact us if you need help.'],
 leaderboard:['How rankings work','Ranked by net P&L from closed trades after trading fees. The footer switch selects Paper or Money. Deposits and invitation rewards do not improve your rank.'],
 setup:['Your trading setup','Paper bets cycle $10 → $50 → $100. Money bets stay $10. Leverage cycles 100× → 500× → 1,000× and locks when you enter. Entry fee: 1% of margin. Profit fee: 10% of positive gross profit. Gross P&L is capped at ± your margin. Money has a 30-second voluntary hold; Paper can exit immediately.'],
 execution:['Estimated until execution','Chart motion follows Hyperliquid prices in the live product. Trading is settled by the backend using a fresh execution midpoint. The displayed return is an estimate, after entry and profit fees. No blockchain gas is required to open or close a backend trade.'],
 risk:['Trade risk','Leverage amplifies small price moves. The existing gross P&L cap is ± margin; fees still apply. A stale price disables new entry and voluntary exit until fresh pricing returns. Changing tabs or modes does not close an open trade.'],
 paper:['Paper Hands','Simplified leveraged BTC trading. $10 bet on 1000x leverage. Only two choices up or down. Login with telegram to play on paper hands.'],
 public:['Public trading history','Only public closed-trade results are shown: net P&L, entry and exit prices, leverage and time held. Wallet addresses, deposits and account balances remain private.'],
 referrals:['Rewards for a good invitation','Earn 10% in Paper or 5% in Money from a friend’s positive net profit on closed winning trades after fees. Yellow Hands funds the reward; the friend keeps their full winnings. No rewards on deposits, returned stakes, losses or referral rewards. One level, ongoing. Paper rewards are virtual.'],
 invitation:['Confirm your invitation','Accept within seven days of joining, before your first trade. One inviter per account. Self-referrals and referral rings are not allowed. Shared links must preserve the invitation code through Telegram login.'],
 treasury:['Public reserves, private accounts','USDT reserves back USD balances. Native GRAM deposits are converted to USDT before credit. Native GRAM is retained for network costs. The 80/20 reserve and hot-liquidity split is a target; it is not proof that multisig controls or an automatic rebalancer are active. Treasury balances are not an independent solvency audit.'],
 lp:['Liquidity mechanics','LP allocation moves existing internal USD credit into pool shares. It does not fund the treasury wallet. LP capital bears trader P&L and earns pool fees. Removal waits for open trades to settle. Funding a treasury or moving reserves requires the existing owner-wallet or multisig approvals. No automatic refill is introduced.'],
 receipt:['Receipt verified','Production must link a confirmed transaction receipt before marking the withdrawal Received. This preview contains no real receipt or transaction.'],
 explorer:['Public treasury link','The live product opens the configured treasury in a TON explorer. This design preview has sample balances and deliberately does not use a real account.'],
 terms:['Trading terms','Keep the existing product terms and risk acknowledgement. This is a design preview; it does not change any financial rules or accept terms on your behalf.'],
 privacy:['Your privacy','Use the existing privacy policy and consent controls. Public profiles never disclose private wallet or balance information. This preview collects no analytics.'],
 wallets:['Your Telegram wallets','Choose Telegram Money or Walt’s DeFi wallet. Telegram login identifies you; wallet approval connects your funds separately. Walt’s custodial balance is not used. This preview simulates the connection and never requests a signature.'],
 deposit:['USDT and GRAM deposits','USDT on TON credits directly after receipt. Native GRAM is swapped to USDT first, with up to 0.5% slippage. Your trading balance receives the actual confirmed USDT amount. Processing attachments are not a flat network fee; unused gas can return.'],
 beta:['During beta','Wallet transfers use the existing review and receipt checks. Trades run on the backend. This design prototype changes presentation only.']
};
function footer(){const isMoney=state.mode==='money',active=state.route==='leaderboard'||state.route==='history'?'leaderboard':['trading','result'].includes(state.route)?'trading':'profile';$('#footer').innerHTML='<div class="mode-bar"><button class="mode-switch" data-action="mode" role="switch" aria-label="Real money mode" aria-checked="'+isMoney+'"><span>'+ (isMoney?'Money':'Paper Hands')+'</span><span class="toggle" aria-hidden="true"><i></i></span></button></div><nav class="nav-items" aria-label="Main navigation">'+[['leaderboard','trophy','Leaderboard'],['trading','chart','Trading'],['profile','user','Profile']].map(([route,i,label])=>'<button class="nav-item" data-go="'+route+'" '+(active===route?'aria-current="page"':'')+' aria-label="'+label+'">'+icon(i)+'</button>').join('')+'</nav>';}
function render(){screen.dataset.page=state.route;const views={trading,leaderboard,profile,earnings,history,result:resultPage,invite,invitation,withdrawal,settings,treasury,liquidity:()=>treasury(true)};screen.innerHTML=(views[state.route]||trading)();footer();renderChart();renderReview();}
function renderReview(){$('#review-pages').innerHTML=pages.map(([route,label],i)=>'<button data-go="'+route+'" class="'+(state.route===route?'current':'')+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+label+'</button>').join('');}
function navigate(route){if(['deposit','withdraw','support','wallet','language','haptics','consent','analytics'].includes(route)){if(route==='deposit')return depositStart();if(route==='withdraw')return withdrawStart();if(route==='support')return openSheet('support');if(route==='wallet')return openSheet('wallet');if(route==='language')return openSheet('language');if(route==='haptics'){state.haptics=!state.haptics;render();return;}if(route==='consent')return openSheet('consent');if(route==='analytics')return openSheet('analytics');}if(route==='withdrawal'||route==='treasury'||route==='liquidity')state.mode='money';if(route==='liquidity'&&!state.owner)return;state.route=route;location.hash=route;render();screen.scrollTop=0;screen.focus({preventScroll:true});$('#review-pages')?.closest('.review')?.classList.remove('open');}
function setMode(mode){if(state.mode===mode)return;state.mode=mode;closeAll();if(!['trading','leaderboard','history','profile','earnings','invite','result'].includes(state.route))state.route='profile';render();announce((mode==='money'?'Money':'Paper Hands')+' mode. Rankings, balances and history updated.');}
function announce(text){const n=$('#toast');n.textContent=text;n.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.hidden=true,3000);}
function openSheet(type,data={},stack=true){if(sheet.open&&stack&&modal)modalStack.push(modal);else if(!sheet.open){modalStack=[];previousFocus=document.activeElement;}modal={type,data};renderSheet();if(!sheet.open)sheet.showModal();const first=sheet.querySelector('input')||sheet.querySelector('button');first?.focus({preventScroll:true});}
function closeSheet(){if(modalStack.length){modal=modalStack.pop();renderSheet();sheet.querySelector('input,button')?.focus({preventScroll:true});}else closeAll();}
function closeAll(){if(sheet.open)sheet.close();modal=null;modalStack=[];if(previousFocus?.isConnected)previousFocus.focus({preventScroll:true});}
function sheetHeader(name,mode=true){return '<div class="sheet-top"><h2 id="sheet-title">'+name+'</h2><button class="icon quiet" data-action="close" aria-label="Close">'+icon('close')+'</button></div>'+(mode?'<div class="sheet-mode"><span class="pill '+(state.mode==='money'?'money':'')+'">'+(state.mode==='money'?'Money':'Paper Hands')+'</span></div>':'');}
function renderSheet(){if(!modal)return;const {type,data}=modal;let html='';
 if(type==='help'){const [name,body]=helpCopy[data.topic]||helpCopy.beta;html=sheetHeader(name,false)+'<p class="sheet-copy">'+body+'</p><button class="text-link brand" data-action="close">Got it</button>';}
 else if(type==='login')html=sheetHeader('Your first move.',false)+'<img class="login-logo" src="assets/logo.png" alt="Yellow Hands"><p class="sheet-copy">Log in with Telegram to save your Paper Hands balance and trading history.</p><button class="primary" data-action="continue-login"><img class="button-logo" src="assets/logo.png" alt=""> Continue with Telegram</button><button class="text-link" data-action="close">Maybe later</button>';
 else if(type==='wallet')html=sheetHeader('Connect your wallet')+(state.wallet?'<div class="connected-wallet">'+icon('check')+' Connected to '+walletName()+'</div>':'')+'<button class="wallet-option primary" data-action="connect-telegram"><span class="wallet-symbol">'+icon('send')+'</span><span><b>Telegram Money</b><small>Your wallet inside Telegram</small></span>'+icon('chevron')+'</button><button class="wallet-option secondary" data-action="connect-walt"><span class="wallet-symbol">'+icon('wallet')+'</span><span><b>Walt DeFi</b><small>Your DeFi wallet in Walt</small></span>'+icon('chevron')+'</button><div class="wallet-help">'+help('wallets','About Telegram Money and Walt DeFi')+'</div>'+(state.wallet?'<button class="text-link" data-action="disconnect">Disconnect wallet</button>':'');
 else if(type==='support')html=sheetHeader('Talk to us.',false)+'<p class="sheet-copy">Contact our team through <b>@yellowhandsbot</b>.</p><button class="primary" data-action="support-preview">'+icon('chat')+' Open Telegram bot</button>';
 else if(type==='deposit')html=depositSheet();
 else if(type==='deposit-quote')html=depositQuote();
 else if(type==='deposit-pending')html=sheetHeader('Deposit submitted')+'<div class="pending-icon">'+icon('clock')+'</div><div class="flow-title">Waiting for USDT.</div><p class="sheet-copy">'+(state.deposit?.asset==='GRAM'?'Your GRAM must swap to USDT before your USD balance is credited.':'Your USD balance updates after the USDT receipt is confirmed.')+'</p>'+row('Amount sent',number(state.deposit?.amount||10)+' '+(state.deposit?.asset||'USDT'))+row('Status','Pending receipt')+'<button class="secondary" data-action="close">Back to app</button>';
 else if(type==='withdraw')html=withdrawSheet();
 else if(type==='claim')html=sheetHeader('Claim USDT')+row('You receive',number(state.withdrawal?.amount||20)+' USDT')+row('Network','TON Mainnet')+row('To wallet',walletName(state.withdrawal?.walletProvider)+' · UQ…example')+row('Network fee','Shown by your wallet')+'<p class="small-note">A small native GRAM balance is needed for network fees.</p><button class="primary" data-action="sign-claim">'+walletReview(state.withdrawal?.walletProvider)+'</button>';
 else if(type==='trade-detail'){const t=data.trade;html=sheetHeader('BTC '+(t.side===1?'long':'short'))+'<div class="big-return '+color(t.net)+'">'+signed(t.net)+'</div><div class="return-caption">'+(t.net>=0?'+':'')+(t.net/t.margin*100).toFixed(2)+'% net · '+t.leverage.toLocaleString()+'×</div>'+trace(t)+row('Price in',number(t.entry))+row('Price out',number(t.exit))+row('Time inside',duration(t.held))+row('Margin',usd(t.margin))+row('Entry fee',usd(t.entryFee))+row('Profit fee',usd(t.profitFee))+'<button class="primary" data-action="detail-card">Create trade card</button>';}
 else if(type==='help-fees'){const t=currentResult();html=sheetHeader('Fees & execution')+row('Gross P&L',signed(t.gross))+row('Entry fee',usd(t.entryFee))+row('Profit fee',usd(t.profitFee))+row('Net P&L',signed(t.net))+'<p class="sheet-copy">Confirmed backend settlement determines the final result. Returned margin is not earnings.</p><button class="text-link brand" data-action="close">Got it</button>';}
 else if(type==='card')html=sheetHeader('Trade card',false)+cardMarkup(data.trade||currentResult())+'<button class="primary" data-action="share-card">'+icon('send')+' Share card</button><button class="text-link" data-action="save-card">'+icon('download')+' Save card</button>';
 else if(type==='share-invite')html=sheetHeader('Ready to send',false)+'<p class="sheet-copy"><b>Try Yellow Hands with me.</b><br>Practice with Paper Hands, then switch to Money when you’re ready.</p><div class="wallet-summary"><p class="invite-link">t.me/yellowhandsbot?startapp=ref_DEMOYH01</p></div><button class="primary" data-action="share-preview">Open Telegram sharing</button>';
 else if(type==='instagram')html=sheetHeader('Instagram kit',false)+'<div class="trade-card"><div class="card-brand">YELLOW HANDS <span>INVITE</span></div><h2 style="color:var(--yellow);margin:30px 0">Good hands.<br>Good company.</h2><div class="card-data"><div><small>Telegram</small>@yellowhandsbot</div><div><small>Invitation code</small>DEMOYH01</div></div><div class="card-url">Use this link in your bio or a Story link sticker.</div></div><button class="primary" data-action="save-kit">Save invitation visual</button><button class="text-link" data-action="copy">Copy invitation link</button><p class="small-note">Use the same invitation link in your bio or a Story link, alongside the Reel.</p>';
 else if(type==='language')html=sheetHeader('Language',false)+'<p class="sheet-copy">Selected automatically from Telegram.</p>'+['English','Русский','Español','Português','Türkçe','Tiếng Việt','简体中文'].map((l,i)=>'<button class="entry-row" data-language="'+l+'"><span>'+l+'</span><span class="chevron">'+(i===0?icon('check'):'')+'</span></button>').join('');
 else if(type==='consent')html=sheetHeader('Usage analytics',false)+'<p class="sheet-copy">Optional usage events help improve the app. Financial records remain necessary for your account.</p><button class="primary" data-action="allow-analytics">Allow usage analytics</button><button class="secondary" data-action="decline-analytics">Do not allow</button><button class="text-link" data-action="delete-analytics">Request analytics deletion</button>';
 else if(type==='collect')html=sheetHeader('Available rewards')+row('Cash rewards available','3.20 USD')+'<p class="sheet-copy">Move earned rewards to your verified USD trading balance. This is a transfer, not new earnings.</p><button class="primary" data-action="collect-preview">Move 3.20 USD to balance</button>';
 else if(type==='analytics')html=sheetHeader('Private analytics',false)+'<p class="sheet-copy">Owner-only reporting keeps the existing ledger-based totals: sign-ins, deposits, withdrawals, trading, acquisition, referrals and treasury backing.</p><button class="secondary" data-action="analytics-preview">Preview analytics entry</button>';
 else if(type==='lp-add')html=sheetHeader('Allocate to LP')+row('Available USD credit',usd(state.balance.money))+'<label class="form-label" for="lp-amount">USD amount</label><input id="lp-amount" value="10" inputmode="decimal"><p class="small-note">Existing credit → LP shares. Treasury funding is a separate wallet transfer.</p><button class="primary" data-action="lp-preview">Review allocation</button>';
 else if(type==='fund-treasury')html=sheetHeader('Fund treasury',false)+'<p class="sheet-copy">Funding treasury reserves is a separate owner-wallet transfer. It does not mint a user trading balance or LP shares.</p>'+row('Asset','USDT · TON')+row('Wallet approval','Required')+'<button class="secondary" data-action="treasury-preview">Review owner-wallet request</button>';
 else if(type==='exit-app')html=sheetHeader('Design preview',false)+'<p class="sheet-copy">This is the proposed Yellow Hands interface. Every amount, user and action here is illustrative.</p><button class="primary" data-action="close">Keep exploring</button>';
 $('#sheet-body').innerHTML=html;
}
function depositStart(){if(!state.authenticated){pendingDirection='deposit';return openSheet('login');}setMode('money');if(!state.wallet){pendingDirection='deposit';return openSheet('wallet');}state.depositAmount='';state.asset='USDT';openSheet('deposit');}
function depositSheet(){const blocked=state.preview==='backing';return sheetHeader('Deposit')+'<div class="wallet-summary"><div class="wallet-summary-top"><span class="eyebrow">'+walletName()+'</span><button class="text-link" data-action="change-deposit-wallet">Change</button></div>'+row('USDT','142.30 USDT')+row('GRAM','45.80 GRAM')+row('Trading balance',usd(state.balance.money))+'</div><div class="asset-tabs"><button data-asset="USDT" aria-pressed="'+(state.asset==='USDT')+'">USDT<small>TON network</small></button><button data-asset="GRAM" aria-pressed="'+(state.asset==='GRAM')+'">GRAM<small>Converts to USDT</small></button></div><div style="display:flex;align-items:center;justify-content:space-between"><label class="form-label" for="deposit-amount" style="margin-top:8px">'+state.asset+' amount</label>'+help('deposit','How deposits and conversion work')+'</div><div class="input-wrap"><input id="deposit-amount" inputmode="decimal" autocomplete="off" placeholder="0.00" value="'+esc(state.depositAmount)+'" '+(blocked?'disabled':'')+'><span>'+state.asset+'</span></div><div class="presets">'+[25,50,100].map(n=>'<button data-percent="'+n+'" '+(blocked?'disabled':'')+'>'+(n===100?'Max':n+'%')+'</button>').join('')+'</div><p class="error" id="funding-error" role="alert" hidden></p>'+(blocked?'<div class="info">'+icon('pause')+' Treasury verification is unavailable. No funds have been sent.</div>':'')+'<button class="primary" data-action="deposit-quote" '+(blocked?'disabled':'')+'>Review deposit</button>'+(blocked?'<button class="text-link" data-action="retry-backing">Try again</button>':'');}
function depositQuote(){const amount=Number(state.depositAmount),isGram=state.asset==='GRAM',expected=isGram?amount*1.25:amount,min=isGram?expected*.995:expected;return sheetHeader(isGram?'Review conversion':'Review deposit')+row('You send',number(amount)+' '+state.asset)+row('Network','TON Mainnet')+row('Expected credit',number(expected)+' USDT')+(isGram?row('Minimum received',min.toFixed(4)+' USDT')+row('Maximum slippage','0.5%'):'')+row('Wallet',walletName())+row('Network / processing','Shown by your wallet')+'<p class="small-note">'+(isGram?'USD credit follows the actual confirmed USDT swap receipt.':'USD credit follows the confirmed USDT receipt.')+'</p>'+help('deposit','Processing attachment and network fees')+'<button class="primary" data-action="send-deposit">'+walletReview()+'</button><button class="text-link" data-action="close">Change amount</button>';}
function withdrawStart(){if(!state.authenticated)return openSheet('login');setMode('money');if(!state.wallet){pendingDirection='withdraw';return openSheet('wallet');}state.withdrawAmount='';openSheet('withdraw');}
function withdrawSheet(){return sheetHeader('Withdraw USDT')+'<div class="wallet-summary">'+row('Available USD balance',usd(state.balance.money))+'</div><label class="form-label" for="withdraw-amount">USDT amount</label><div class="input-wrap"><input id="withdraw-amount" inputmode="decimal" autocomplete="off" placeholder="0.00" value="'+esc(state.withdrawAmount)+'"><span>USDT</span></div>'+row('To wallet',walletName()+' · UQ…example')+'<button class="text-link wallet-change" data-action="change-withdraw-wallet">Change wallet</button>'+row('Claim limit','25 USDT per claim')+'<div class="status-top"><span class="pill wait">Manual review during beta</span>'+help('manual','Why withdrawals need manual review')+'</div><p class="error" id="funding-error" role="alert" hidden></p><button class="primary" data-action="request-withdrawal">Request withdrawal</button>';}
function error(text){const e=$('#funding-error');if(e){e.hidden=false;e.textContent=text;}}
function openTrade(side){if(!state.authenticated){pendingDirection=side;return openSheet('login');}if(state.preview==='stale')return;if(state.mode==='money'&&!state.wallet){pendingDirection=side;return openSheet('wallet');}const margin=state.mode==='paper'?state.bet:10;if(state.balance[state.mode]<margin*1.01)return openSheet('help',{topic:'low-balance'});state.balance[state.mode]-=margin*1.01;state.positions[state.mode]={side,margin,leverage:state.leverage[state.mode],entry:state.price,openedAt:Date.now()};state.panned=false;render();}
function closeTrade(){const p=positions();if(!p||state.preview==='stale'||state.mode==='money'&&Date.now()-p.openedAt<30000)return;const e=estimate(p),t={...p,...e,entryFee:p.margin*.01,exit:state.price,held:Math.floor((Date.now()-p.openedAt)/1000),mode:state.mode,closed:'Just now',opened:'12:36:28'};state.balance[state.mode]+=e.returned;state.earnings[state.mode]+=e.net;state.results[state.mode]=t;state.newTrades[state.mode].unshift(t);state.positions[state.mode]=null;navigate('result');}
helpCopy['low-balance']=['A little more balance is needed','A $10 Money trade needs $10 margin plus its $0.10 entry fee. Deposit USDT or GRAM before entering. Paper credit cannot fund Money trades.'];
function action(name){
 if(name==='close')return closeSheet();if(name==='mode')return setMode(state.mode==='paper'?'money':'paper');if(name==='money')return setMode('money');if(name==='balance')return state.mode==='money'?depositStart():navigate('profile');if(name==='deposit')return depositStart();if(name==='withdraw')return withdrawStart();if(name==='login')return openSheet('login');if(name==='exit')return closeTrade();if(name==='bet'){state.bet=[10,50,100][([10,50,100].indexOf(state.bet)+1)%3];render();return;}if(name==='leverage'){const list=[100,500,1000];state.leverage[state.mode]=list[(list.indexOf(state.leverage[state.mode])+1)%3];render();return;}if(name==='live'){state.panned=false;render();return;}if(name==='menu')return navigate('settings');if(name==='leave')return openSheet('exit-app');
 if(name==='continue-login'){state.authenticated=true;closeAll();announce('Sample Telegram session connected.');let pending=pendingDirection;pendingDirection=null;if(typeof pending==='number')openTrade(pending);else if(pending==='deposit')depositStart();else if(pending==='withdraw')withdrawStart();else render();return;}
 if(name==='change-deposit-wallet'){pendingDirection='deposit';return openSheet('wallet');}if(name==='change-withdraw-wallet'){pendingDirection='withdraw';return openSheet('wallet');}
 if(name==='connect-telegram'||name==='connect-walt'){state.wallet=true;state.walletProvider=name==='connect-walt'?'walt':'telegram';closeAll();announce('Sample '+walletName()+' connected.');const pending=pendingDirection;pendingDirection=null;if(typeof pending==='number')openTrade(pending);else if(pending==='deposit')depositStart();else if(pending==='withdraw')withdrawStart();else render();return;}
 if(name==='disconnect'){state.wallet=false;closeAll();render();return;}if(name==='logout'){state.authenticated=false;state.wallet=false;closeAll();render();announce('Logged out. Existing trades remain open.');return;}
 if(name==='retry-board'){state.preview='normal';$('#preview-state').value='normal';render();return;}if(name==='retry-backing'){state.preview='normal';$('#preview-state').value='normal';renderSheet();return;}
 if(name==='deposit-quote'){state.depositAmount=$('#deposit-amount').value.trim();const value=Number(state.depositAmount),available=state.asset==='GRAM'?45.25:142.30;if(!Number.isFinite(value)||value<=0)return error('Enter a positive amount.');if(value>available)return error(state.asset==='GRAM'?'Keep 0.55 GRAM for processing and network fees.':'Not enough USDT in this wallet.');openSheet('deposit-quote');return;}
 if(name==='send-deposit'){state.deposit={asset:state.asset,amount:Number(state.depositAmount),expected:Number(state.depositAmount)*(state.asset==='GRAM'?1.25:1)};modalStack=[];openSheet('deposit-pending',{},false);return;}
 if(name==='request-withdrawal'){state.withdrawAmount=$('#withdraw-amount').value.trim();let amount=Number(state.withdrawAmount);if(!Number.isFinite(amount)||amount<=0)return error('Enter a positive USDT amount.');if(amount>25)return error('Up to 25 USDT per claim. Split larger requests.');if(amount>state.balance.money)return error('This amount exceeds your available USD balance.');if(state.withdrawal&&state.withdrawal.status!=='paid')return error('This preview already has an active withdrawal request.');state.balance.money-=amount;state.withdrawal={amount,status:'requested',created:Date.now(),walletProvider:state.walletProvider};closeAll();navigate('withdrawal');return;}
 if(name==='claim')return openSheet('claim');if(name==='sign-claim'){state.withdrawal.status='submitted';closeAll();render();return;}
 if(name==='card')return openSheet('card',{trade:currentResult()});if(name==='detail-card')return openSheet('card',{trade:modal.data.trade});if(name==='share-card')return announce('Preview: the native share sheet would open with this result card.');if(name==='save-card')return announce('Preview: save the confirmed result image and trade screenshot.');if(name==='share-invite')return openSheet('share-invite');if(name==='share-preview')return announce('Preview: Telegram chat picker. No message has been sent.');if(name==='instagram')return openSheet('instagram');if(name==='copy')return announce('Preview invitation: t.me/yellowhandsbot?startapp=ref_DEMOYH01');if(name==='save-kit')return announce('Preview: save the visual, then add the invitation to your bio or Story link.');
 if(name==='accept-invite'){if(!state.authenticated)return openSheet('login');if(state.accepted){state.mode='paper';return navigate('trading');}state.accepted=true;render();return;}
 if(name==='collect')return openSheet('collect');if(name==='collect-preview'){closeAll();announce('Preview: move only available rewards; lifetime earnings stay unchanged.');return;}
 if(name==='support-preview')return announce('Preview: opens @yellowhandsbot support. No message has been sent.');if(name==='allow-analytics'||name==='decline-analytics'){state.consent=name==='allow-analytics';closeAll();render();return;}if(name==='delete-analytics')return announce('Preview: confirm and request deletion of optional usage events.');if(name==='fund-treasury')return openSheet('fund-treasury');if(name==='lp-add')return openSheet('lp-add');if(name.endsWith('-preview'))return announce('Design preview only. No funds or permissions changed.');
}
document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b||b.disabled)return;if(b.dataset.go){event.preventDefault();navigate(b.dataset.go);}else if(b.dataset.action)action(b.dataset.action);else if(b.dataset.help){if(b.dataset.help==='fees')openSheet('help-fees');else openSheet('help',{topic:b.dataset.help});}else if(b.dataset.side)openTrade(Number(b.dataset.side));else if(b.dataset.user){state.selectedTrader=b.dataset.user;navigate('history');}else if(b.dataset.trade!==undefined){const trade=historyTrades()[Number(b.dataset.trade)];if(state.route==='history')trade.username=(boardRows().find(u=>u.id===state.selectedTrader)||boardRows()[0]).name;openSheet('trade-detail',{trade});}else if(b.dataset.asset){state.depositAmount=$('#deposit-amount')?.value||state.depositAmount;state.asset=b.dataset.asset;state.depositAmount='';renderSheet();}else if(b.dataset.percent){const value=(state.asset==='GRAM'?45.25:142.3)*Number(b.dataset.percent)/100;state.depositAmount=value.toFixed(state.asset==='GRAM'?4:2);$('#deposit-amount').value=state.depositAmount;}else if(b.dataset.range){state.range=b.dataset.range;render();}else if(b.dataset.language){closeAll();announce('Preview language: '+b.dataset.language+'. Production reuses all seven translations.');}else if(b.dataset.demo)demo(b.dataset.demo);});
sheet.addEventListener('cancel',event=>{event.preventDefault();closeSheet();});sheet.addEventListener('click',event=>{const r=sheet.getBoundingClientRect();if(event.target===sheet&&(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom))closeSheet();});
let pointerStart=null;screen.addEventListener('pointerdown',e=>{if(e.target.closest('#market-chart'))pointerStart=e.clientX;});screen.addEventListener('pointerup',e=>{if(pointerStart!==null&&Math.abs(e.clientX-pointerStart)>24){state.panned=true;render();}pointerStart=null;});
$('#review-toggle').onclick=()=>$('.review').classList.toggle('open');
$('#preview-state').onchange=e=>{closeAll();state.preview=e.target.value;state.authenticated=state.preview!=='signedout';state.wallet=state.preview!=='signedout';state.owner=state.preview==='owner';if(state.preview==='low'){state.balance.money=3;state.mode='money';state.route='trading';}else if(state.preview==='empty'||state.preview==='board-error')state.route='leaderboard';else if(state.preview==='backing'){state.mode='money';state.route='profile';}else if(state.preview==='owner'){state.mode='money';state.route='liquidity';}else if(state.preview==='signedout')state.route='trading';else state.route='trading';render();$('.review').classList.remove('open');};
function demo(which){if(which==='reset'){location.reload();return;}if(which==='elapsed'){if(positions()){positions().openedAt-=30000;render();}else announce('Open a sample trade first.');return;}if(which==='approve'||which==='hold'){if(!state.withdrawal){state.mode='money';state.withdrawal={amount:20,status:'requested',created:Date.now()-180000,walletProvider:state.walletProvider};state.balance.money-=20;}state.withdrawal.status=which==='approve'?'ready':'held';closeAll();state.mode='money';navigate('withdrawal');announce(which==='approve'?'Sample operator approval received.':'Sample request placed on hold.');return;}if(which==='receipt'){if(state.deposit){state.balance.money+=state.deposit.expected;state.deposit=null;closeAll();state.mode='money';navigate('profile');announce('Sample USDT receipt confirmed; USD balance credited.');return;}if(state.withdrawal?.status==='submitted'){state.withdrawal.status='paid';closeAll();navigate('withdrawal');announce('Sample claim receipt confirmed.');return;}announce('Submit a sample deposit or claim first.');}}
function tick(){if(document.hidden||state.preview==='stale')return;if(!reduced.matches){state.phase++;state.price=78124.61+Math.sin(state.phase*.022)*12+Math.sin(state.phase*.16)*1.1;renderChart();}const p=positions();if(p&&state.route==='trading'){const e=estimate(p),left=state.mode==='money'?Math.max(0,30-Math.floor((Date.now()-p.openedAt)/1000)):0;$('#active-pnl').textContent=(e.net>=0?'+':'')+(e.net/p.margin*100).toFixed(2)+'%';$('#active-pnl').className='pnl '+color(e.net);$('#active-value').textContent=signed(e.net);$('#exit-title').textContent=left?'Hold '+left+'s':'CASH OUT';$('#exit-return').textContent=usd(e.returned)+' estimated return';const btn=$('[data-action="exit"]');btn.disabled=left>0;$('#time-inside').textContent=duration((Date.now()-p.openedAt)/1000);}}
setInterval(tick,250);setInterval(()=>{if(state.withdrawal&&state.route==='withdrawal'&&$('#withdraw-time'))$('#withdraw-time').textContent=state.withdrawal.status==='paid'?'Receipt confirmed':'Waiting '+duration((Date.now()-state.withdrawal.created)/1000);},1000);
$('.telegram-title [data-action=leave]').innerHTML=icon('close');$('.telegram-title [data-action=menu]').innerHTML=icon('more');
const params=new URLSearchParams(location.search);if(params.get('mode')==='money')state.mode='money';const initial=location.hash.slice(1);if(pages.some(p=>p[0]===initial)&&!['deposit'].includes(initial))state.route=initial;
render();

window.addEventListener('hashchange',()=>{const route=location.hash.slice(1)||'trading';if(pages.some(p=>p[0]===route)&&route!=='deposit'&&state.route!==route){closeAll();state.route=route;render();screen.scrollTop=0;}});

document.addEventListener('input',event=>{if(event.target.id==='deposit-amount')state.depositAmount=event.target.value;if(event.target.id==='withdraw-amount')state.withdrawAmount=event.target.value;if(event.target.closest('#sheet')&&document.querySelector('#funding-error'))document.querySelector('#funding-error').hidden=true;});

window.addEventListener('resize',renderChart);

// Review links open isolated sample states only; never ship these controls in production.
const review=params.get('review');
if(review==='active')openTrade(1);
else if(review==='card'){state.route='result';render();openSheet('card',{trade:currentResult()});}
else if(review==='deposit'){state.mode='money';state.route='profile';state.walletProvider='walt';render();depositStart();}
else if(review==='login'){state.authenticated=false;state.wallet=false;state.route='trading';render();openSheet('login');}
else if(review==='wallet'){state.mode='money';state.wallet=false;state.route='profile';render();pendingDirection='deposit';openSheet('wallet');}
